<template><DashboardModuleCard data-figma-node="349:510" title="快捷指令" :loading="loading" :error="error" :empty="!commands.length && !loading && !error"><div class="command-widget"><h2>快捷指令</h2><button v-for="command in visibleCommands" :key="command.id" type="button" :data-command-id="command.id" @click="$emit('run',command.id)">{{ command.title }}</button></div></DashboardModuleCard></template>
<script setup>import{computed}from'vue';import DashboardModuleCard from'../patterns/DashboardModuleCard.vue';const props=defineProps({commands:{type:Array,default:()=>[]},loading:Boolean,error:{type:String,default:''}});defineEmits(['run']);const visibleCommands=computed(()=>props.commands.slice(0,2))</script>
<style scoped>.command-widget{display:grid;height:100%;box-sizing:border-box;grid-template-rows:auto 1fr 1fr;gap:8px;padding:14px}.command-widget h2{margin:0 0 2px;font-size:16px}.command-widget button{overflow:hidden;border:1px dashed rgb(245 246 238 / 20%);border-radius:10px;background:#151814;color:#d9ddcf;font-size:11px;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}.command-widget button:hover{border-color:#d7ff63;color:#d7ff63}</style>
